pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use two addresses: alice (first caller) and bank (reentrant caller)
        address alice = address(0x1);
        address bank = address(0x2);

        // Deploy a simple attacker contract that reenters airDrop()
        Attacker att = new Attacker(address(c));

        // Set tokenBalance[alice] = 0 (default)
        vm.prank(alice);
        // alice calls airDrop once
        c.airDrop();

        // Now alice has tokenBalance[alice] = 20 in correct version
        // In buggy version, we need a reentrant call: set up so that bank is the caller
        // But the only way to trigger reentrancy is during the execution of airDrop itself
        // Since modifier supportsToken requires msg.sender to be a Bank contract that returns the correct hash,
        // we can make addr(0x2) a Bank that calls airDrop again inside supportsToken
        // However, supportsToken is called BEFORE the modifier body in _nonReentrant (because it's applied after _nonReentrant).
        // Actually in C: function airDrop() public _nonReentrant hasNoBalance supportsToken
        // The modifiers execute left-to-right: first _nonReentrant (which acquires lock, then body, then releases),
        // then hasNoBalance (checks balance), then supportsToken (calls Bank(msg.sender).supportsToken()).
        // In the buggy version, _nonReentrant does: require(!_locked); _; _locked = true; _locked = false;
        // So the lock is never set during the execution of the other modifiers and function body -> reentrancy possible.
        // We need msg.sender to be a contract that, when called via supportsToken, reenters airDrop.
        // But supportsToken is a modifier on airDrop itself; inside the modifier, it calls Bank(msg.sender).supportsToken().
        // That call happens BEFORE the function body (airDrop code) executes (due to modifier order).
        // So if msg.sender is a malicious Bank that calls airDrop again during its supportsToken(),
        // it will re-enter before the first airDrop's function body completes.
        // In the correct version, _locked is true at that point, so require(!_locked) fails and catch reverts.
        // In buggy version, _locked is false, so reentry succeeds, adding another 20.

        // So we make the attacker contract be the msg.sender for the first airDrop call
        // and inside supportsToken, it calls c.airDrop() again.

        vm.prank(address(att));
        try c.airDrop() {
            // success
        } catch {
            // revert
        }
        // Now check tokenBalance[address(att)]
        // In correct version: first call enters, lock set; supportsToken calls out to att.supportsToken(),
        // which tries to call c.airDrop() again; that fails because lock is true, so the inner call reverts,
        // outer call continues, adds 20 to att. So tokenBalance[att] = 20.
        // In buggy version: locked never set, so inner call succeeds, adds 20 twice? No, outer adds 20, inner adds 20 -> total 40.
        uint256 balance = c.tokenBalance(address(att));
        // This assertion holds for P (balance = 20) but fails for M (balance = 40)
        assertTrue(balance == 20);
    }
}

contract Attacker {
    C public c;
    constructor(address _c) { c = C(_c); }
    function supportsToken() external view returns (bytes32) {
        // Reenter airDrop via another call
        c.airDrop();
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

