        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Alice calls airDrop via the attacker contract; the attacker's supportsToken() will call airDrop again
        vm.prank(address(attacker));
        c.airDrop();

        // In the correct version, the reentrant call reverts, so only the outer call gives tokens to attacker
        // In the buggy version, both calls succeed, giving double tokens to attacker
        uint256 balance = c.tokenBalance(address(attacker));
        assertTrue(balance == 20, "Expected balance 20 in correct version");
    }
}

contract ReentrantAttacker {
    C public c;
    constructor(C _c) { c = _c; }
    function supportsToken() external view returns (bytes32) {
        // This is called by the Bank check during airDrop
        // We don't reenter here because the check happens before the modifier lock
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function attack() public {
        // This is called after the first airDrop sets _locked to false
        c.airDrop();
    }
}

